package org.walkwithgod.config;
import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import org.walkwithgod.user.*;import org.walkwithgod.mentor.*;import org.walkwithgod.devotion.*;import org.walkwithgod.trivia.*;import java.util.*;
@Configuration public class DataSeeder {@Bean CommandLineRunner seed(UserRepository users,MentorProfileRepository mentors,DevotionRepository devotions,TriviaQuestionRepository trivia,PasswordEncoder encoder){return args->{if(users.findByEmailIgnoreCase("admin@walkwithgod.local").isEmpty()){AppUser a=new AppUser();a.setName("WalkWithGod Admin");a.setEmail("admin@walkwithgod.local");a.setPasswordHash(encoder.encode("ChangeMe123!"));a.setRole(Role.ADMIN);users.save(a);}if(mentors.count()==0){AppUser m=new AppUser();m.setName("Pastor Daniel");m.setEmail("mentor@walkwithgod.local");m.setPasswordHash(encoder.encode("ChangeMe123!"));m.setRole(Role.MENTOR);users.save(m);MentorProfile p=new MentorProfile();p.setUser(m);p.setVerified(true);p.setChurch("Community Church");p.setBio("Accredited Christian leader focused on discipleship, prayer and Bible study.");p.setYearsExperience(12);p.setSpecialties("Bible study,Prayer,Discipleship");p.setRating(5.0);mentors.save(p);}if(devotions.count()==0){AppUser author=users.findByEmailIgnoreCase("mentor@walkwithgod.local").orElseThrow();Devotion d=new Devotion();d.setTitle("When you need courage for the next step");d.setScripture("Joshua 1:9");d.setBody("Faith does not mean that every step feels easy. It means we choose to walk forward trusting God's presence. Today, name the next faithful step you can take, pray over it, and invite someone you trust to encourage you.");d.setAuthor(author);devotions.save(d);}if(trivia.count()==0){TriviaQuestion q=new TriviaQuestion();q.setQuestion("Who built the ark?");q.setOptionsJson("[\"Moses\",\"Noah\",\"Abraham\",\"David\"]");q.setAnswerIndex(1);q.setExplanation("Genesis 6–9 tells the account of Noah and the ark.");q.setDifficulty("EASY");trivia.save(q);}};}}
